  "justification": {
    "anchor": {
      "probability": 0.68,
      "basis": "Anchored on IOM Missing Migrants Project context and recent annual tolls (~2,100–2,500) to ground expectations, with February 2026 counts (~606) providing the primary signal."
    },
    "factor_updates": [
      {
        "factor": "Current pace through February 2026",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "606 deaths/missing by late February implies a high near-term pace; if continued into Mar–May, the total could exceed 1,000."
      },
      {
        "factor": "Weather/sea-state severity",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "Cyclone Harry and rough seas have raised mortality risk, boosting near-term total."
      },
      {
        "factor": "Reporting gaps/undercounting",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Under-counting could mean the true toll is higher, increasing likelihood of 1,000+ by May."
      },
      {
        "factor": "Policy shifts and reduced SAR capacity",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Crackdowns and funding constraints can reduce rescues, elevating fatalities."
      },
      {
        "factor": "Seasonality: winter-to-spring",
        "direction": "down",
        "magnitude": "weak",
        "rationale": "Spring typically improves conditions, potentially reducing fatalities modestly; offsets some uplift."
      }
    ],
    "synthesis_rationale": "The factors were integrated into a Bayesian-like update, treating strong pace, weather risk, and undercounting as positive updates to the probability of crossing 1,000 by May, while seasonality provides a small downward adjustment. A post-hoc calibration yields a posterior around 0.96, acknowledging possible correlations among factors and data uncertainty."
  }
}

